@startuml

class Bettor {}

class Race {
  + runners : Runner[]
  + winner : Runner
}

class Runner {
  + name : string
}

class Jockey {}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "*" Bet : places
Race "1" -- "1..*" Runner : contains
Runner "1" -- "1" Jockey : ridden by
Bet "*" -- "1" Race : refers to
Bet "*" -- "1" Runner : refers to

@enduml

